(function () {
  'use strict';
  const S=window.StarkSystem,F=window.StarkFulfillment;if(!S || !F)return;
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=(value,currency='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(value || 0);
  const date=value=>value?String(value).slice(0,10):'—';
  const badge=(value,color='')=>`<span class="sys-badge ${color || (/CANCELLED|ISSUES|REJECTED|UNKNOWN/.test(value)?'red':/SHIPPED|DELIVERED|ACKNOWLEDGED|VALIDATED/.test(value)?'green':/UNVALIDATED|QUEUED|REQUESTED/.test(value)?'orange':'')}" >${esc(String(value).replaceAll('_',' '))}</span>`;
  const link=(path,label,primary=false)=>`<a class="sys-btn${primary?' primary':''}" href="${S.url(path)}">${esc(label)}</a>`;
  const button=(action,id,label,primary=false)=>`<button class="sys-btn${primary?' primary':''}" type="button" data-op="${action}" data-id="${esc(id)}">${esc(label)}</button>`;
  const panel=(title,body)=>`<section class="sys-panel"><div class="sys-panel-head"><h2>${esc(title)}</h2></div>${body}</section>`;
  const table=(headers,rows,id='')=>`<div class="sys-table-wrap"><table class="sys-table" ${id?`id="${id}"`:''}><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('') || `<tr><td class="sys-empty" colspan="${headers.length}">No records match this view.</td></tr>`}</tbody></table></div>`;
  const field=(label,name,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
  const select=(label,name,options,value='',extra='')=>`<label>${esc(label)}<select name="${name}" ${extra}>${options.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;
  const textarea=(label,name,value='',extra='')=>`<label class="op-wide">${esc(label)}<textarea name="${name}" rows="3" ${extra}>${esc(value)}</textarea></label>`;
  const read=(root,name)=>root.querySelector(`[name="${name}"]`)?.value || '';
  const params=new URLSearchParams(location.search),page=document.body?.dataset.fulfillmentPage;
  let root,query=params.get('search') || '',issueFilter='',plan=null,uploadName='',selectedDay=localDay(),busy=false;
  const NAV={
    orders:[['order-management/index.html','All open orders'],['order-management/issues.html','Order issues'],['order-management/unvalidated.html','Unvalidated'],['order-management/cancelled.html','Cancelled'],['order-management/new-order.html','Create customer order']],
    tpl:[['3pl-management/index.html','Overview'],['3pl-management/order-history.html','Order history & API'],['3pl-management/shipment-requests.html','Shipment requests'],['3pl-management/orders.html','Manage 3PL orders'],['3pl-management/ship-orders.html','Ship 3PL orders'],['3pl-management/upload-shipments.html','Upload shipments']],
    shipping:[['shipping/index.html','Ship orders · Sarasota'],['shipping/daily-report.html','Daily shipment report']],
    procurement:[['procurement/index.html','Open vendor POs'],['procurement/new-po.html','Create vendor PO']],
    transportation:[['transportation/index.html','Overview'],['freight-estimator.html','Freight estimator'],['freight-consolidate.html','Freight consolidation'],['shipment-tracking.html','Shipment tracking']]
  };
  function localDay(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=k=>parts.find(p=>p.type===k).value;return get('year')+'-'+get('month')+'-'+get('day');}
  function notice(message,error=false){window.StarkSystemUI?.notice(message,error);const live=root?.querySelector('#op-live');if(live){live.textContent=message;live.setAttribute('role',error?'alert':'status');}}
  function layout(group,title,description,content,actions='') {
    root.innerHTML=`<div id="op-live" class="visually-hidden" role="status" aria-live="polite"></div><div class="system-heading"><div><div class="system-eyebrow">${esc(group==='tpl'?'3PL management':group==='orders'?'Order management':group==='shipping'?'Shipping':group==='transportation'?'Transportation':'Procurement')}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="system-actions">${actions}</div></div><nav class="op-tabs" aria-label="Module pages">${NAV[group].map(([path,label])=>`<a href="${S.url(path)}" ${new URL(S.url(path)).pathname===location.pathname?'class="active" aria-current="page"':''}>${esc(label)}</a>`).join('')}</nav>${content}`;
  }
  function download(name,body,type='text/plain') {const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function csv(rows){return rows.map(row=>row.map(value=>{let s=String(value??'');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
  function modal(title,body,submit,label='Save') {
    const wrap=document.createElement('div');wrap.className='sys-modal-backdrop op-modal';
    wrap.innerHTML=`<section class="sys-modal" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><h2>${esc(title)}</h2><div class="op-modal-body">${body}</div><p class="op-form-error" role="alert" hidden></p><div class="sys-modal-footer"><button class="sys-btn" type="button" data-close>${submit?'Cancel':'Close'}</button>${submit?`<button class="sys-btn primary" type="button" data-save>${esc(label)}</button>`:''}</div></section>`;
    const former=document.activeElement;let saving=false;const close=()=>{if(saving)return;wrap.remove();document.removeEventListener('keydown',keys);former?.focus();};
    const focusable=()=>[...wrap.querySelectorAll('button,input,select,textarea,a[href]')].filter(e=>!e.disabled && !e.hidden);
    const keys=e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const nodes=focusable(),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};
    document.addEventListener('keydown',keys);wrap.querySelector('[data-close]').onclick=close;wrap.addEventListener('click',e=>{if(e.target===wrap)close();});
    if(submit)wrap.querySelector('[data-save]').onclick=async()=>{if(saving)return;saving=true;const save=wrap.querySelector('[data-save]');save.disabled=true;try{const ok=await submit(wrap);saving=false;if(ok!==false)close();}catch(error){const message=wrap.querySelector('.op-form-error');message.hidden=false;message.textContent=error.message;saving=false;}finally{save.disabled=false;}};
    document.body.append(wrap);(wrap.querySelector('input,select,textarea') || wrap.querySelector('[data-close]')).focus();return wrap;
  }
  const account=(state,order)=>state.enterprise.accounts.find(a=>a.id===order.accountId);
  function orderRows(state,orders){return orders.map(order=>{
    const problems=F.pending(order)?F.assess(state,order):[],customer=account(state,order),action=F.pending(order)?button('validate',order.id,'Validate')+link('order-management/new-order.html?id='+encodeURIComponent(order.id),'Edit'):!F.final(order)&&!['3PL','DROPSHIP'].includes(order.fulfillment?.kind)?button('edit-delivery',order.id,'Delivery / warehouse'):'';
    return `<tr><td><button class="op-record-link" data-op="order-detail" data-id="${esc(order.id)}">${esc(order.po)}</button><small>${esc(order.orderNumber || order.id)}</small></td><td>${esc(customer?.name || '')}</td><td>${badge(order.type)}<small>${badge(order.status)}</small></td><td>${order.lines.map(l=>`<span>${esc(l.model || state.enterprise.inventory.find(i=>i.sku===l.sku)?.model || l.sku)} × ${l.qty}</span>`).join('<br>')}</td><td>${money(F.total(order),customer?.currency)}<small>${esc(F.warehouseName(order))}</small></td><td>${date(order.inHandsDate)}<small>Created ${date(order.createdAt)}</small></td><td>${esc(order.tracking || '—')}</td><td>${problems.length?problems.map(i=>`<span class="op-issue">${esc(i.label)}${i.model?' · '+esc(i.model):''}</span>`).join(''):'—'}</td><td><div class="op-row-actions">${action}${!F.final(order)?button('cancel-order',order.id,'Cancel'):''}</div></td></tr>`;
  });}
  function filteredOrders(state) {
    return state.enterprise.orders.filter(order=>{
      if(page==='orders' && F.final(order))return false;
      if(page==='order-cancelled' && order.status!=='CANCELLED')return false;
      if(page==='order-unvalidated' && order.validation?.state!=='UNVALIDATED' || page==='order-unvalidated' && F.final(order))return false;
      if(page==='order-issues' && (F.final(order) || !F.pending(order) || !F.assess(state,order).length))return false;
      if(issueFilter && !F.assess(state,order).some(i=>i.code===issueFilter))return false;
      return F.orderSearch(state,order,query);
    }).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  }
  function renderOrders() {
    const state=S.getState(),counts={open:state.enterprise.orders.filter(o=>!F.final(o)).length,issues:state.enterprise.orders.filter(o=>!F.final(o)&&F.pending(o)&&F.assess(state,o).length).length,unvalidated:state.enterprise.orders.filter(o=>!F.final(o)&&o.validation?.state==='UNVALIDATED').length,cancelled:state.enterprise.orders.filter(o=>o.status==='CANCELLED').length};
    const title={'orders':'All open customer orders','order-issues':'Order issues','order-unvalidated':'Unvalidated customer orders','order-cancelled':'Cancelled customer orders'}[page];
    const stats=`<div class="op-stats">${[['All open',counts.open,'index.html'],['Order issues',counts.issues,'issues.html'],['Unvalidated',counts.unvalidated,'unvalidated.html'],['Cancelled',counts.cancelled,'cancelled.html']].map(([label,count,path])=>`<a class="op-stat" href="${S.url('order-management/'+path)}"><span>${label}</span><strong>${count}</strong></a>`).join('')}</div>`;
    const toolbar=`<div class="sys-toolbar"><label class="op-search">Search orders<input id="op-search" type="search" placeholder="PO#, order#, tracking#, model# or date (YYYY-MM-DD)" value="${esc(query)}"></label>${page==='order-issues'?select('Issue type','issue-filter',[['','All issues'],...Object.entries(F.ISSUES)],issueFilter):''}<span id="op-result-count" class="op-result-count">${filteredOrders(state).length} orders</span></div>`;
    layout('orders',title,'Find customer orders and resolve validation issues before stock allocation or shipment.',stats+toolbar+panel('Customer order register',table(['Customer PO / order#','Customer','Type / status','Models / units','Total / warehouse','Dates','Tracking','Issues','Actions'],orderRows(state,filteredOrders(state)),'op-order-table')),link('order-management/new-order.html','Create customer order',true));
    root.querySelector('#op-search').oninput=e=>{query=e.target.value;paintOrderRows();};root.querySelector('[name="issue-filter"]')?.addEventListener('change',e=>{issueFilter=e.target.value;paintOrderRows();});
  }
  function paintOrderRows(){const state=S.getState(),orders=filteredOrders(state);root.querySelector('#op-order-table tbody').innerHTML=orderRows(state,orders).join('') || '<tr><td colspan="9" class="sys-empty">No matching customer orders.</td></tr>';root.querySelector('#op-result-count').textContent=orders.length+' orders';}
  function customerLine(line={model:'',qty:1,price:''}) {
    return `<div class="op-line"><label>Model#<input data-line-model list="op-models" value="${esc(line.model || line.sku || '')}" required maxlength="150" placeholder="Model# or catalog SKU"></label><label>Unit price<input data-line-price type="number" step="0.01" min="0.01" value="${esc(line.price)}" required></label><label>Quantity<input data-line-qty type="number" min="1" step="1" value="${esc(line.qty)}" required></label><label>Line total<output data-line-total>0.00</output></label><button class="sys-btn" data-op="remove-line" type="button" aria-label="Remove order line">Remove</button></div>`;
  }
  function renderOrderEntry() {
    const state=S.getState(),existing=state.enterprise.orders.find(o=>o.id===params.get('id'));
    if(existing && (!F.pending(existing)||F.final(existing))){layout('orders','Customer order','This order has already entered execution.',panel('Order editing',`<div class="sys-panel-body">Open orders with issues can be edited before allocation. ${link('order-management/index.html','Open orders')}</div>`));return;}
    const event=Object.values(state.events||{}).flat().find(e=>e.id===params.get('event'));
    const eventAccount=event && state.enterprise.accounts.find(a=>a.name.toLowerCase()===String(event.customer).toLowerCase());
    const values=existing || {type:event?.poType?.includes('HOLD')?'HOLD_PO':'FIRM_PO',po:event?.poNumber || '',accountId:eventAccount?.id || '',purpose:event?'EVENT':'REGULAR',inHandsDate:event?.inHandsDate || '',region:S.regionCode(params.get('region') || S.getRegion()),address:{},warehouseId:'SARASOTA',shipping:{method:'UPS Ground'},lines:event?.items?.map(i=>({model:i.model,qty:i.quantity,price:''})) || [{model:'',qty:1,price:''}]};
    const form=`<form id="op-customer-form" class="op-form"><fieldset><legend>Order & customer</legend><div class="op-fields">${select('Order type','type',[['HOLD_PO','Hold PO'],['BULK_PO','Bulk PO'],['FIRM_PO','Firm PO']],values.type)}${field('Customer PO#','po',values.po,'text','required maxlength="100"')}${select('Customer','accountId',[['','Choose customer'],...state.enterprise.accounts.map(a=>[a.id,a.name])],values.accountId,'required')}${select('Region','region',[['US','US'],['EU','Europe'],['CA','Canada']],values.region)}${select('Purpose','purpose',[['REGULAR','Regular customer order'],['EVENT','Event order']],values.purpose)}${select('Program (optional)','programId',[['','No program'],...state.enterprise.programs.filter(p=>p.status==='LIVE'&&p.accountId===values.accountId).map(p=>[p.id,p.name])],values.programId)}${field('In-hands date','inHandsDate',values.inHandsDate,'date')}${field('Hold expiry (Hold PO only)','holdUntil',date(values.holdUntil)==='—'?'':date(values.holdUntil),'date')}</div></fieldset><fieldset><legend>Delivery address</legend><div class="op-fields">${['line1','line2','line3','city','state','zip'].map((key,i)=>field(['Address line 1','Address line 2','Address line 3','City','State / province','ZIP / postal code'][i],'address-'+key,values.address?.[key] || '')).join('')}${textarea('Instructions','instructions',values.instructions)}</div></fieldset><fieldset><legend>Shipping & warehouse</legend><div class="op-fields">${select('Shipping method','shippingMethod',[['','Choose method'],['UPS Ground','UPS Ground'],['UPS 2nd Day','UPS 2nd Day'],['UPS Next Day','UPS Next Day'],['FedEx Ground','FedEx Ground'],['FedEx Express','FedEx Express'],['LTL','LTL'],['FTL','FTL'],['Customer pickup','Customer pickup'],['Other','Other']],values.shipping?.method)}${select('Assigned warehouse','warehouseId',F.WAREHOUSES.map(w=>[w.id,w.name]),values.warehouseId)}${field('Third-party shipping account#','thirdPartyAccount',values.shipping?.thirdPartyAccount)}${field('Third-party billing ZIP','thirdPartyZip',values.shipping?.thirdPartyZip)}</div></fieldset><fieldset><legend>Order lines</legend><datalist id="op-models">${state.enterprise.inventory.map(i=>`<option value="${esc(i.sku)}">${esc(i.region+' · '+i.model+' · '+i.title)}</option>`).join('')}</datalist><div id="op-order-lines">${values.lines.map(customerLine).join('')}</div><button class="sys-btn" type="button" data-op="add-line">Add model</button><div class="op-order-total">Order total <output id="op-total">0.00</output></div></fieldset><div id="op-validation-results" class="op-validation" aria-live="polite"></div><div class="op-form-footer"><p>Unvalidated orders remain saved without reserving stock.</p><button class="sys-btn" type="submit" name="intent" value="draft">Save unvalidated</button><button class="sys-btn primary" type="submit" name="intent" value="validate">Save & validate</button></div></form>`;
    layout('orders',existing?'Edit customer order':'Create customer order','Enter customer details, delivery instructions and order lines. Hold, Bulk and Firm orders share one record.',panel('Customer order entry',form));
    const node=root.querySelector('form');node.addEventListener('input',updateTotals);
    node.addEventListener('change',e=>{if(e.target.matches('[data-line-model]')){const row=e.target.closest('.op-line'),item=F.resolveItem(S.getState(),e.target.value,read(node,'region'));if(item && !row.querySelector('[data-line-price]').value)row.querySelector('[data-line-price]').value=item.standardPrice || '';updateTotals();}if(e.target.name==='accountId'){node.querySelector('[name="programId"]').innerHTML='<option value="">No program</option>'+S.getState().enterprise.programs.filter(p=>p.accountId===e.target.value&&p.status==='LIVE').map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');updateTotals();}});
    node.onsubmit=e=>{e.preventDefault();if(busy || !node.reportValidity())return;busy=true;try{
      const input={...Object.fromEntries(['type','po','accountId','region','purpose','programId','inHandsDate','holdUntil','instructions','warehouseId','shippingMethod','thirdPartyAccount','thirdPartyZip'].map(k=>[k,read(node,k)])),eventId:existing?.eventId || event?.id || null,address:Object.fromEntries(['line1','line2','line3','city','state','zip'].map(k=>[k,read(node,'address-'+k)])),lines:[...node.querySelectorAll('.op-line')].map(r=>({model:r.querySelector('[data-line-model]').value,qty:Number(r.querySelector('[data-line-qty]').value),price:Number(r.querySelector('[data-line-price]').value)}))};
      const id=existing?F.editDraft(existing.id,input,existing.updatedAt,existing.recordRevision || 0):F.createDraft(input),validate=e.submitter?.value==='validate',result=validate?F.validateDraft(id):{ok:false,issues:[]};
      navigate(result.ok?'order-management/index.html?search='+encodeURIComponent(input.po):validate?'order-management/issues.html?search='+encodeURIComponent(input.po):'order-management/unvalidated.html?search='+encodeURIComponent(input.po));
    }catch(error){const box=node.querySelector('#op-validation-results');box.className='op-validation error';box.textContent=error.message;notice(error.message,true);}finally{busy=false;}};
    updateTotals();
  }
  function updateTotals(){const form=root.querySelector('#op-customer-form');if(!form)return;let cents=0;for(const row of form.querySelectorAll('.op-line')){const q=Number(row.querySelector('[data-line-qty]').value)||0,p=Number(row.querySelector('[data-line-price]').value)||0,amount=Math.round(p*100)*q;cents+=amount;row.querySelector('output').textContent=(amount/100).toFixed(2);}const currency=S.getState().enterprise.accounts.find(a=>a.id===read(form,'accountId'))?.currency || 'USD';form.querySelector('#op-total').textContent=money(cents/100,currency);}
  function navigate(path){const url=S.url(path);if(window.StarkNavigation)window.StarkNavigation.navigate(url);else location.assign(url);}
  function showOrder(id){const state=S.getState(),order=state.enterprise.orders.find(o=>o.id===id);if(!order)return;
    modal('Customer PO '+order.po,`<dl class="op-details"><dt>Order#</dt><dd>${esc(order.orderNumber || order.id)}</dd><dt>Customer</dt><dd>${esc(account(state,order)?.name)}</dd><dt>Type / status</dt><dd>${badge(order.type)} ${badge(order.status)}</dd><dt>Warehouse</dt><dd>${esc(F.warehouseName(order))}</dd><dt>Address</dt><dd>${esc(order.address?Object.values(order.address).filter(Boolean).join(', '):order.shipping?.destination || 'Not recorded')}</dd><dt>Instructions</dt><dd>${esc(order.instructions || '—')}</dd><dt>In-hands date</dt><dd>${date(order.inHandsDate)}</dd><dt>Shipping method</dt><dd>${esc(order.shipping?.method || '—')}</dd><dt>Third-party account / ZIP</dt><dd>${esc(order.shipping?.thirdPartyAccount || '—')} / ${esc(order.shipping?.thirdPartyZip || '—')}</dd><dt>Tracking</dt><dd>${esc(order.tracking || '—')}</dd><dt>Total</dt><dd>${money(F.total(order),account(state,order)?.currency)}</dd></dl>${table(['Model#','Quantity','Unit price','Total'],order.lines.map(l=>`<tr><td>${esc(l.model || l.sku)}</td><td>${l.qty}</td><td>${money(l.price,account(state,order)?.currency)}</td><td>${money(l.qty*l.price,account(state,order)?.currency)}</td></tr>`))}`);
  }
  function editDeliveryModal(id){const order=S.getState().enterprise.orders.find(o=>o.id===id);modal('Delivery & warehouse · '+order.po,`<p>Update shipping details while preserving order quantities and existing allocations.</p><div class="op-fields">${['line1','line2','line3','city','state','zip'].map((k,i)=>field(['Address line 1','Address line 2','Address line 3','City','State / province','ZIP / postal code'][i],'address-'+k,order.address?.[k] || '')).join('')}${field('In-hands date','inHandsDate',order.inHandsDate,'date')}${select('Assigned warehouse','warehouseId',F.WAREHOUSES.map(w=>[w.id,w.name]),F.warehouseId(order) || 'SARASOTA')}${field('Shipping method','shippingMethod',order.shipping?.method || '')}${field('Third-party shipping account#','thirdPartyAccount',order.shipping?.thirdPartyAccount)}${field('Third-party billing ZIP','thirdPartyZip',order.shipping?.thirdPartyZip)}${textarea('Instructions','instructions',order.instructions)}</div>`,w=>{F.updateDelivery(id,{address:Object.fromEntries(['line1','line2','line3','city','state','zip'].map(k=>[k,read(w,'address-'+k)])),...Object.fromEntries(['inHandsDate','warehouseId','shippingMethod','thirdPartyAccount','thirdPartyZip','instructions'].map(k=>[k,read(w,k)]))},order.recordRevision || 0);render();notice('Delivery details and warehouse assignment saved.');});}
  function renderShipping(){const state=S.getState(),orders=state.enterprise.orders.filter(o=>F.warehouseId(o)==='SARASOTA'&&!F.final(o)&&!['3PL','DROPSHIP'].includes(o.fulfillment?.kind)&&F.orderSearch(state,o,query));
    layout('shipping','Ship orders · Sarasota','All open orders assigned to Sarasota. Validation and Hold PO status control dispatch eligibility.',`<div class="sys-toolbar"><label class="op-search">Search Sarasota orders<input id="op-search" type="search" placeholder="PO#, model#, order# or date" value="${esc(query)}"></label></div>`+panel('Sarasota shipping queue',table(['Customer PO','Customer','Models / units','In-hands','Status','Action'],orders.map(o=>`<tr><td><button class="op-record-link" data-op="order-detail" data-id="${esc(o.id)}">${esc(o.po)}</button><small>${esc(o.orderNumber || o.id)}</small></td><td>${esc(account(state,o)?.name)}</td><td>${o.lines.map(l=>esc(l.model || l.sku)+' × '+l.qty).join('<br>')}</td><td>${date(o.inHandsDate)}</td><td>${badge(o.status)}${o.type==='HOLD_PO'?'<small>Hold · redemption required</small>':''}</td><td>${F.pending(o)?link('order-management/issues.html?search='+encodeURIComponent(o.po),'Resolve / validate'):o.type==='HOLD_PO'?link('order-management/hold-redemption.html','Open hold'):F.assess(state,o).length?button('edit-delivery',o.id,'Review delivery / stock'):button('ship-warehouse',o.id,'Confirm & ship',true)}</td></tr>`))));
    root.querySelector('#op-search').onchange=e=>{query=e.target.value;renderShipping();};
  }
  function shipWarehouseModal(id){const order=S.getState().enterprise.orders.find(o=>o.id===id);modal('Ship Sarasota order '+order.po,`<p>Confirm physical picking and packing, then record the actual shipment. This updates inventory and the daily shipment report.</p><div class="op-fields">${field('Carrier','carrier','UPS')}${field('Service','service',order.shipping?.method || 'Ground')}${field('Tracking#','tracking','','text','required maxlength="200"')}${field('Carton / packing reference','carton')}${textarea('Shipment notes','notes')}</div><label class="op-check"><input type="checkbox" name="packed"> Picking and packing are completed for the remaining order quantity.</label>`,w=>{F.shipWarehouse(id,{carrier:read(w,'carrier'),service:read(w,'service'),tracking:read(w,'tracking'),carton:read(w,'carton'),notes:read(w,'notes'),packed:w.querySelector('[name="packed"]').checked});render();notice('Shipment saved. Stock and the daily report were updated.');},'Confirm shipment');}
  function dailyRows(){return [['Customer PO','Order#','Customer','Model#','Quantity','Carrier','Service','Tracking#','Shipped at (UTC)','Warehouse'],...F.dailyShipments(selectedDay).map(p=>[p.po,p.orderNumber,p.customer,p.model,p.qty,p.carrier,p.service,p.tracking,p.shippedAt,'Sarasota'])];}
  function renderDaily(){const rows=F.dailyShipments(selectedDay);layout('shipping','Daily shipment report','Sarasota shipments grouped by shipment date in America/New_York.',`<div class="sys-toolbar">${field('Shipment date','shipment-day',selectedDay,'date')}<span class="op-result-count">${rows.length} shipment lines · ${rows.reduce((n,r)=>n+r.qty,0)} units</span></div>`+panel('Daily warehouse shipments',table(['Customer PO','Customer','Model#','Units','Carrier / service','Tracking#','Shipped at'],rows.map(p=>`<tr><td>${esc(p.po)}</td><td>${esc(p.customer)}</td><td>${esc(p.model)}</td><td>${p.qty}</td><td>${esc(p.carrier)}<small>${esc(p.service)}</small></td><td>${esc(p.tracking)}</td><td>${esc(new Date(p.shippedAt).toLocaleString('en-US',{timeZone:'America/New_York'}))}</td></tr>`))),button('export-daily','','Export CSV')+button('export-daily-xlsx','','Export Excel'));
    root.querySelector('[name="shipment-day"]').onchange=e=>{selectedDay=e.target.value || localDay();renderDaily();};}
  function requestRows(state,requests){return requests.map(r=>{const o=state.enterprise.orders.find(o=>o.id===r.customerOrderId),partner=state.logistics.tplNodes.find(n=>n.id===r.nodeId),trans=r.transmission || {state:'QUEUED'};return `<tr><td><b>${esc(o?.po || r.customerOrderId)}</b><small>${esc(r.id)}</small></td><td>${esc(partner?.name || r.nodeId)}</td><td>${badge(r.status)}</td><td>${badge(trans.state)}${trans.remoteOrderId?`<small>Partner order ${esc(trans.remoteOrderId)}</small>`:''}${trans.error?`<small class="op-error-text">${esc(trans.error)}</small>`:''}</td><td>${date(r.createdAt)}</td><td><div class="op-row-actions">${button('request-detail',r.id,'Details')}${button('export-request',r.id,'Export JSON')}${r.status!=='CANCELLED'?['QUEUED','REJECTED'].includes(trans.state)?button('send-request',r.id,'Send for processing',true):button('check-request',r.id,'Refresh API status'):''}</div></td></tr>`;});}
  function renderTPLHome(){const state=S.getState(),requests=state.logistics.tplRequests || [],shipments=state.logistics.tplShipments;layout('tpl','3PL management','Manage partner orders, shipment requests and confirmations independently from transportation.',`<div class="op-stats">${[['Shipment requests',requests.length],['Pending dispatch',shipments.filter(s=>!['DISPATCHED','DELIVERED','CANCELLED'].includes(s.status)).length],['Dispatched',shipments.filter(s=>s.status==='DISPATCHED').length],['API queued',requests.filter(r=>r.transmission?.state==='QUEUED'&&r.status!=='CANCELLED').length]].map(([label,count])=>`<div class="op-stat"><span>${label}</span><strong>${count}</strong></div>`).join('')}</div><div class="op-module-grid">${NAV.tpl.slice(1).map(([path,label])=>`<a class="op-module-card" href="${S.url(path)}"><strong>${esc(label)}</strong><span>Open workspace →</span></a>`).join('')}</div>`+panel('Latest processing requests',table(['Customer PO / request','3PL partner','Shipment status','API delivery','Created','Actions'],requestRows(state,requests.slice().reverse().slice(0,10))))+`<p class="op-support-links">${link('3pl-management/network.html','Partner network & stock')}${link('3pl-management/reconciliation.html','Stock reconciliation')}${link('3pl-management/integrations.html','API connection')}</p>`,link('3pl-management/shipment-requests.html','Create shipment request',true));}
  function renderHistory(){const state=S.getState(),requests=(state.logistics.tplRequests || []).filter(r=>{const o=state.enterprise.orders.find(o=>o.id===r.customerOrderId);return !query || [r.id,r.transmission?.remoteOrderId,r.customerOrderId,o?.po,o?.orderNumber].join(' ').toLowerCase().includes(query.toLowerCase());}).slice().reverse();layout('tpl','3PL order history & processing API','Review queued, acknowledged and failed transmissions. Acknowledgment confirms API receipt; shipment status remains separate.',`<div class="sys-toolbar"><label class="op-search">Search requests<input id="op-search" type="search" value="${esc(query)}" placeholder="Customer PO, order# or request ID"></label></div>`+panel('Processing history',table(['Customer PO / request','3PL partner','Shipment status','API delivery','Created','Actions'],requestRows(state,requests)))+panel('Partner shipment history',table(['Customer PO','Shipment ID','Model#','Quantity','Status','Tracking','Created'],state.logistics.tplShipments.filter(s=>!query || [s.orderId,s.id,s.sku,s.model,s.tracking].join(' ').toLowerCase().includes(query.toLowerCase())).slice().reverse().map(s=>`<tr><td>${esc(s.orderId)}</td><td>${esc(s.id)}</td><td>${esc(s.model || state.enterprise.inventory.find(i=>i.sku===s.sku)?.model || s.sku)}</td><td>${s.qty}</td><td>${badge(s.status)}</td><td>${esc(s.tracking || '—')}</td><td>${date(s.createdAt)}</td></tr>`))));root.querySelector('#op-search').onchange=e=>{query=e.target.value;renderHistory();};}
  function renderRequestForm(){const state=S.getState(),orders=state.enterprise.orders.filter(o=>!F.final(o)&&o.type!=='HOLD_PO'&&!['3PL','DROPSHIP'].includes(o.fulfillment?.kind));layout('tpl','Shipment requests','Select a customer order and partner. The request validates partner stock, reserves it and links each shipment to the customer order.',panel('Create 3PL shipment request',`<form class="op-form" id="op-request-form"><div class="op-fields">${select('Customer order','orderId',[['','Choose customer order'],...orders.map(o=>[o.id,o.po+' · '+account(state,o)?.name+' · '+o.status])],'','required')}${select('3PL partner','nodeId',[['','Choose active partner'],...state.logistics.tplNodes.filter(n=>n.status==='ACTIVE').map(n=>[n.id,n.name])],'','required')}</div><div id="op-request-preview" class="op-validation"></div><div class="op-form-footer"><button type="submit" class="sys-btn primary">Create shipment request</button></div></form>`));
    const form=root.querySelector('form');form.onchange=()=>{const current=S.getState(),o=current.enterprise.orders.find(o=>o.id===read(form,'orderId'));const box=form.querySelector('#op-request-preview');if(!o){box.textContent='';return;}const issues=read(form,'nodeId')?F.assess(current,o,read(form,'nodeId')):[];box.innerHTML=table(['Model#','Quantity','Shipping method','In-hands'],o.lines.map(l=>`<tr><td>${esc(l.model || l.sku)}</td><td>${l.qty}</td><td>${esc(o.shipping?.method || '—')}</td><td>${date(o.inHandsDate)}</td></tr>`))+issues.map(i=>`<p class="op-error-text">${esc(i.label+': '+i.detail)}</p>`).join('');};
    form.onsubmit=e=>{e.preventDefault();try{if(!form.reportValidity())return;F.request3PL(read(form,'orderId'),read(form,'nodeId'));navigate('3pl-management/order-history.html');}catch(error){notice(error.message,true);form.querySelector('#op-request-preview').insertAdjacentHTML('beforeend',`<p class="op-error-text">${esc(error.message)}</p>`);}};
  }
  function renderPartnerOrders(){const state=S.getState(),ship=state.logistics.tplShipments.filter(s=>(page!=='tpl-ship' || !['DISPATCHED','DELIVERED','CANCELLED'].includes(s.status))&&(!query || [s.orderId,s.id,s.model,s.sku,s.tracking].join(' ').toLowerCase().includes(query.toLowerCase())));layout('tpl',page==='tpl-ship'?'Ship orders · 3PL':'Manage 3PL orders','Partner shipments retain their order, model, quantity and status. Multi-line orders close after all shipment quantities are dispatched.',`<div class="sys-toolbar"><label class="op-search">Search partner orders<input id="op-search" type="search" value="${esc(query)}" placeholder="PO#, model#, shipment# or tracking#"></label></div>`+panel('Partner shipment queue',table(['Customer PO / shipment','Partner','Model#','Quantity','Status','Tracking','Action'],ship.map(s=>`<tr><td><b>${esc(s.orderId)}</b><small>${esc(s.id)}</small></td><td>${esc(state.logistics.tplNodes.find(n=>n.id===s.nodeId)?.name || s.nodeId)}</td><td>${esc(s.model || state.enterprise.inventory.find(i=>i.sku===s.sku)?.model || s.sku)}</td><td>${s.qty}</td><td>${badge(s.status)}</td><td>${esc(s.tracking || '—')}</td><td>${!s.customerOrderId?'<small>Legacy partner record · link required</small>':s.status==='PICKING'?button('ship-3pl',s.id,'Ship order',true):s.status==='REQUESTED'?button('advance-3pl',s.id,'Mark accepted'):['ACCEPTED','DELAYED'].includes(s.status)?button('advance-3pl',s.id,'Start picking'):s.status==='DISPATCHED'?button('advance-3pl',s.id,'Confirm delivered'):''}</td></tr>`))),link('3pl-management/upload-shipments.html','Upload shipment confirmations'));
    root.querySelector('#op-search').onchange=e=>{query=e.target.value;renderPartnerOrders();};}
  function shipPartnerModal(id){const shipment=S.getState().logistics.tplShipments.find(s=>s.id===id);modal('Ship partner order '+shipment.orderId,`<p>Record the 3PL’s actual dispatch confirmation for ${esc(shipment.model || shipment.sku)} · ${shipment.qty} units.</p><div class="op-fields">${field('Carrier','carrier','UPS')}${field('Tracking#','tracking','','text','required')}</div>`,w=>{F.ship3PL(id,{carrier:read(w,'carrier'),tracking:read(w,'tracking')});render();notice('Partner shipment and customer order balance updated.');},'Confirm 3PL shipment');}
  function renderUpload(){layout('tpl','Upload 3PL shipments','Upload CSV or Excel confirmations. Preview every row before applying an atomic import. Already imported confirmations are skipped.',panel('Shipment import',`<div class="sys-panel-body"><p>Use shipmentId, quantity, tracking#, carrier and shippedDate (YYYY-MM-DD). Alternatively provide an exact orderRef and model#. Each row must match the full remaining shipment quantity.</p><div class="op-upload-toolbar"><label class="op-file-label">Choose shipment file<input id="op-shipment-file" type="file" accept=".csv,.xlsx,.xls" aria-label="Upload 3PL shipment confirmations"></label>${button('shipment-template','','Download CSV template')}${button('pending-shipments-template','','Export pending shipment rows')}</div><p id="op-upload-status" role="status">${esc(uploadName)}</p><div id="op-upload-preview"></div><button class="sys-btn primary" id="op-import-confirm" type="button" ${!plan || plan.rows.some(r=>r.error)?'disabled':''}>Apply verified import</button></div>`));
    const file=root.querySelector('#op-shipment-file');file.onchange=async()=>{if(!file.files[0])return;try{const current=file.files[0];if(current.size>5*1024*1024)throw new Error('Use a shipment file up to 5 MB.');if(!window.XLSX)throw new Error('The local workbook reader did not load. Reload the page.');const wb=window.XLSX.read(await current.arrayBuffer(),{type:'array',cellDates:true}),rows=window.XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:'',raw:false});plan=F.importPlan(rows);uploadName=current.name;paintUpload();}catch(error){plan=null;notice(error.message,true);root.querySelector('#op-upload-status').textContent=error.message;root.querySelector('#op-import-confirm').disabled=true;}};
    root.querySelector('#op-import-confirm').onclick=()=>{try{const result=F.applyImport(plan);plan=null;uploadName='Imported '+result.imported+' shipment rows; skipped '+result.duplicates+' existing confirmations.';renderUpload();notice(uploadName);}catch(error){notice(error.message,true);}};paintUpload();}
  function paintUpload(){if(!plan)return;const errors=plan.rows.filter(r=>r.error).length;root.querySelector('#op-upload-status').textContent=uploadName+' · '+plan.rows.length+' rows · '+errors+' errors';root.querySelector('#op-upload-preview').innerHTML=table(['File row','Shipment ID','Quantity','Tracking','Carrier','Result'],plan.rows.map(r=>`<tr><td>${r.line}</td><td>${esc(r.shipmentId)}</td><td>${esc(r.qty ?? '')}</td><td>${esc(r.tracking || '')}</td><td>${esc(r.carrier || '')}</td><td>${r.error?`<span class="op-error-text">${esc(r.error)}</span>`:badge(r.result==='duplicate'?'ALREADY IMPORTED':'READY')}</td></tr>`));root.querySelector('#op-import-confirm').disabled=!!errors;}
  function renderIntegrations(){layout('tpl','3PL processing API','Requests use an authenticated server connector. Partner credentials stay on the server.',panel('Connection status',`<div class="sys-panel-body"><p>${esc(window.StarkSystemCloud?.getStatus().active?'Shared workspace connected. Configure and deploy the included 3PL connector before sending.':'Local workspace. Connect the shared organization workspace in Data Center to enable authenticated API sends.')}</p><p>Create a shipment request, review its payload in Order history, then choose Send for processing. UNKNOWN means delivery could not be confirmed: refresh API status and reconcile with the partner before resending or cancelling.</p><p>Outbound contract: <code>stark.3pl.order.v1</code>. The request ID is the idempotency key. The server accepts only partner endpoints configured for your organization.</p><div class="system-actions">${link('data-center.html','Connect shared workspace')}${link('3pl-management/order-history.html','Open API order history',true)}</div></div>`));}
  function renderProcurement(){const state=S.getState(),orders=state.enterprise.purchaseOrders.filter(p=>!['RECEIVED','CANCELLED','DISPATCHED'].includes(p.status) || p.purpose!=='DROPSHIP'&&!['RECEIVED','CANCELLED'].includes(p.status)).filter(p=>!query || [p.po,p.tracking,p.notes,state.enterprise.vendors.find(v=>v.id===p.vendorId)?.name,...p.lines.flatMap(l=>[l.model,l.sku,l.vendorItem,l.title])].join(' ').toLowerCase().includes(query.toLowerCase()));layout('procurement','Open vendor PO management','Track supplier POs, shipping references, notes and packing slips. Receiving remains linked to the warehouse workflow.',`<div class="sys-toolbar"><label class="op-search">Search vendor POs<input id="op-search" type="search" value="${esc(query)}" placeholder="PO#, vendor, model#, vendor item# or tracking#"></label></div>`+panel('Open vendor purchase orders',table(['Vendor PO','Supplier','Purpose','Models / quantity','ETA','Tracking','Status','Packing slips','Actions'],orders.map(p=>`<tr><td><button class="op-record-link" data-op="po-detail" data-id="${esc(p.id)}">${esc(p.po)}</button><small>${esc(p.notes || '')}</small></td><td>${esc(state.enterprise.vendors.find(v=>v.id===p.vendorId)?.name || '')}</td><td>${badge(p.purpose || 'INVENTORY')}</td><td>${p.lines.map(l=>esc(l.model || state.enterprise.inventory.find(i=>i.sku===l.sku)?.model || l.sku)+' × '+l.qty).join('<br>')}</td><td>${date(p.eta)}</td><td>${esc(p.tracking || '—')}</td><td>${badge(p.status)}</td><td>${(p.attachments || []).length}</td><td><div class="op-row-actions">${button('edit-po',p.id,'Tracking / notes')}${button('po-detail',p.id,'Packing slips')}${link(p.purpose==='DROPSHIP'?'vendor-po-management.html':'warehouse-management/receiving.html',p.purpose==='DROPSHIP'?'Supplier dispatch':'Receive in WMS')}</div></td></tr>`))),link('procurement/new-po.html','Create vendor PO',true));root.querySelector('#op-search').onchange=e=>{query=e.target.value;renderProcurement();};}
  function poLine(state,line={}){return `<div class="op-po-line"><div class="op-fields">${select('Model#','line-sku',[['','Choose catalog model'],...state.enterprise.inventory.map(i=>[i.sku,(i.region || 'US')+' · '+i.model+' · '+i.title])],line.sku,'required')}${field('Vendor item#','line-vendorItem',line.vendorItem,'text','required')}${field('Title','line-title',line.title,'text','required')}${field('Quantity','line-qty',line.qty || 1,'number','required min="1" step="1"')}${field('Unit cost','line-cost',line.cost || '', 'number','required min="0.01" step="0.01"')}${textarea('Description','line-description',line.description,'required')}</div><button type="button" class="sys-btn" data-op="remove-po-line">Remove line</button></div>`;}
  function renderPOEntry(){const state=S.getState();layout('procurement','Create vendor PO','Add catalog models with vendor item numbers, titles, descriptions and quantities.',panel('Vendor purchase order entry',`<form class="op-form" id="op-po-form"><div class="op-fields">${field('Vendor PO#','po','PO-'+Date.now(),'text','required')}${select('Vendor','vendorId',[['','Choose active vendor'],...state.enterprise.vendors.filter(v=>v.status==='ACTIVE').map(v=>[v.id,v.name])],'','required')}${select('Purpose','purpose',[['INVENTORY','Inventory'],['EVENT','Event'],['DROPSHIP','Dropship']],'INVENTORY')}${field('Expected delivery','eta',new Date(Date.now()+7*86400000).toISOString().slice(0,10),'date','required')}${select('Receiving warehouse','warehouse',F.WAREHOUSES.map(w=>[w.name,w.name]),'Sarasota')}${select('Linked dropship customer order','customerOrderId',[['','No linked order'],...state.enterprise.orders.filter(o=>!F.final(o)&&o.fulfillment?.kind==='DROPSHIP').map(o=>[o.id,o.po])])}${textarea('PO notes','notes')}</div><div id="op-po-lines">${poLine(state)}</div><button type="button" class="sys-btn" data-op="add-po-line">Add model</button><p class="op-helper">Packing slips can be attached after saving the PO.</p><div id="op-po-error" class="op-form-error" role="alert"></div><div class="op-form-footer"><button class="sys-btn primary" type="submit">Create vendor PO</button></div></form>`));
    const form=root.querySelector('form');form.addEventListener('change',e=>{if(e.target.name==='line-sku'){const item=S.getState().enterprise.inventory.find(i=>i.sku===e.target.value),row=e.target.closest('.op-po-line');if(item){row.querySelector('[name="line-title"]').value=item.title;row.querySelector('[name="line-description"]').value=item.description || item.title;row.querySelector('[name="line-cost"]').value=item.cost || '';}}});
    form.onsubmit=e=>{e.preventDefault();try{if(!form.reportValidity())return;F.createPO({...Object.fromEntries(['po','vendorId','purpose','eta','warehouse','customerOrderId','notes'].map(k=>[k,read(form,k)])),lines:[...form.querySelectorAll('.op-po-line')].map(r=>({sku:read(r,'line-sku'),vendorItem:read(r,'line-vendorItem'),title:read(r,'line-title'),description:read(r,'line-description'),qty:Number(read(r,'line-qty')),cost:Number(read(r,'line-cost'))}))});navigate('procurement/index.html?search='+encodeURIComponent(read(form,'po')));}catch(error){form.querySelector('#op-po-error').textContent=error.message;notice(error.message,true);}};
  }
  function editPOModal(id){const po=S.getState().enterprise.purchaseOrders.find(p=>p.id===id);modal('Vendor PO '+po.po+' · tracking & notes',`<div class="op-fields">${field('Carrier','carrier',po.carrier)}${field('Tracking#','tracking',po.tracking)}${textarea('Notes','notes',po.notes)}</div>`,w=>{F.updatePO(id,{carrier:read(w,'carrier'),tracking:read(w,'tracking'),notes:read(w,'notes')},po.updatedAt || po.issuedAt,po.recordRevision || 0);render();notice('Vendor PO tracking and notes saved.');});}
  function showPO(id){const state=S.getState(),po=state.enterprise.purchaseOrders.find(p=>p.id===id);if(!po)return;
    const wrap=modal('Vendor PO '+po.po,`<dl class="op-details"><dt>Vendor</dt><dd>${esc(state.enterprise.vendors.find(v=>v.id===po.vendorId)?.name)}</dd><dt>Status</dt><dd>${badge(po.status)}</dd><dt>Tracking</dt><dd>${esc(po.tracking || '—')}</dd><dt>Notes</dt><dd>${esc(po.notes || '—')}</dd></dl>${table(['Model#','Vendor item#','Title','Description','Quantity'],po.lines.map(l=>`<tr><td>${esc(l.model || state.enterprise.inventory.find(i=>i.sku===l.sku)?.model || l.sku)}</td><td>${esc(l.vendorItem || '—')}</td><td>${esc(l.title || '—')}</td><td>${esc(l.description || '—')}</td><td>${l.qty}</td></tr>`))}<h3>Packing slip attachments</h3><p>PDF, PNG or JPEG up to 1 MB each; five files and 2 MB total per PO. Attachments are included in workspace backups and shared synchronization.</p><label class="op-file-label">Attach packing slip<input type="file" id="op-packing-file" accept=".pdf,.png,.jpg,.jpeg"></label><div id="op-attachments"></div><p id="op-attachment-status" role="status"></p>`);
    const paint=()=>{const current=S.getState().enterprise.purchaseOrders.find(p=>p.id===id);wrap.querySelector('#op-attachments').innerHTML=(current.attachments || []).map(a=>`<div class="op-attachment"><span>${esc(a.name)} · ${Math.ceil(a.size/1024)} KB</span>${button('download-attachment',a.id,'Download')}${button('remove-attachment',a.id,'Remove')}</div>`).join('') || '<p>No packing slips attached.</p>';};paint();
    wrap.querySelector('#op-packing-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;e.target.disabled=true;try{F.attachPO(id,await F.attachmentFromFile(file));paint();render();wrap.querySelector('#op-attachment-status').textContent='Packing slip attached.';}catch(error){wrap.querySelector('#op-attachment-status').textContent=error.message;}finally{e.target.disabled=false;e.target.value='';}};
    wrap.addEventListener('click',e=>{const b=e.target.closest('[data-op]');if(!b)return;const current=S.getState().enterprise.purchaseOrders.find(p=>p.id===id),attachment=(current.attachments || []).find(a=>a.id===b.dataset.id);if(!attachment)return;if(b.dataset.op==='download-attachment'){const bytes=Uint8Array.from(atob(attachment.data),c=>c.charCodeAt(0));download(attachment.name,bytes,attachment.mime);}if(b.dataset.op==='remove-attachment'){F.removeAttachment(id,attachment.id);paint();render();}});
  }
  function requestDetail(id){const state=S.getState(),request=(state.logistics.tplRequests || []).find(r=>r.id===id);if(!request)return;modal('3PL processing request',`<dl class="op-details"><dt>Request ID</dt><dd>${esc(request.id)}</dd><dt>Shipment status</dt><dd>${badge(request.status)}</dd><dt>API delivery</dt><dd>${badge(request.transmission.state)}</dd><dt>Partner order ID</dt><dd>${esc(request.transmission.remoteOrderId || '—')}</dd><dt>API attempts</dt><dd>${request.transmission.attempts || 0}</dd><dt>Last result</dt><dd>${esc(request.transmission.error || '—')}</dd></dl><h3>API delivery events</h3>${table(['Time','State','Result'],(request.transmission.events || []).map(e=>`<tr><td>${esc(e.time)}</td><td>${badge(e.state)}</td><td>${esc(e.error || '—')}</td></tr>`))}<h3>Order payload</h3><pre class="op-json">${esc(JSON.stringify(request.payload,null,2))}</pre>`);}
  function sendModal(id,statusOnly=false){const sample=S.getState().mode==='sample';modal(statusOnly?'Refresh API delivery status':'Send order to the 3PL',statusOnly?'<p>Check the stored server result without dispatching another request.</p>':'<p>Send the shipment request’s customer address, order lines and shipping instructions to the configured 3PL partner for processing.</p>'+(sample?'<label class="op-check"><input name="working-records" type="checkbox"> I reviewed the customer and shipping details. Treat this workspace as working records; preserve its current data.</label>':''),async w=>{if(sample&&!statusOnly){if(!w.querySelector('[name="working-records"]').checked)throw new Error('Review the selected request and confirm it contains working records before sending.');S.transaction('WORKSPACE_MODE_UPDATED','Existing records retained as working data.',s=>s.mode='working');}const result=await F.sendForProcessing(id,statusOnly);render();notice(result.state==='ACKNOWLEDGED'?'Partner API receipt confirmed.':'API status: '+result.state);},statusOnly?'Refresh status':'Send for processing');}
  function actions(event){const b=event.target.closest('[data-op]');if(!b || !root.contains(b))return;const id=b.dataset.id;try{switch(b.dataset.op){
    case'order-detail':return showOrder(id);
    case'edit-delivery':return editDeliveryModal(id);
    case'validate':{const result=F.validateDraft(id);render();notice(result.ok?'Order validated and allocated.':'Order saved in the issues queue.',!result.ok);return;}
    case'cancel-order':return modal('Cancel customer order','<p>Cancel the unshipped order and release its allocation. Orders already sent to the 3PL require partner reconciliation first.</p>',()=>{S.cancelOrder(id);render();notice('Customer order cancelled.');},'Cancel order');
    case'add-line':root.querySelector('#op-order-lines').insertAdjacentHTML('beforeend',customerLine());updateTotals();return;
    case'remove-line':if(root.querySelectorAll('.op-line').length<=1)throw new Error('Keep at least one order line.');b.closest('.op-line').remove();updateTotals();return;
    case'ship-warehouse':return shipWarehouseModal(id);
    case'export-daily':return download('Sarasota-shipments-'+selectedDay+'.csv',csv(dailyRows()),'text/csv;charset=utf-8');
    case'export-daily-xlsx':{if(!window.XLSX)throw new Error('The local workbook library did not load.');const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(dailyRows()),'Daily shipments');return XLSX.writeFile(wb,'Sarasota-shipments-'+selectedDay+'.xlsx');}
    case'advance-3pl':S.advanceShipment(id);render();notice('Partner shipment status updated.');return;
    case'ship-3pl':return shipPartnerModal(id);
    case'request-detail':return requestDetail(id);
    case'export-request':{const request=(S.getState().logistics.tplRequests||[]).find(r=>r.id===id);return download(request.id+'.json',JSON.stringify(request.payload,null,2),'application/json');}
    case'send-request':return sendModal(id);
    case'check-request':return sendModal(id,true);
    case'shipment-template':return download('3PL-shipment-template.csv',csv([['shipmentId','orderRef','model#','quantity','tracking#','carrier','shippedDate']]),'text/csv;charset=utf-8');
    case'pending-shipments-template':{const state=S.getState();return download('3PL-pending-shipments.csv',csv([['shipmentId','orderRef','model#','quantity','tracking#','carrier','shippedDate'],...state.logistics.tplShipments.filter(s=>s.customerOrderId&&!['DISPATCHED','DELIVERED','CANCELLED'].includes(s.status)).map(s=>[s.id,s.orderId,s.model || state.enterprise.inventory.find(i=>i.sku===s.sku)?.model,s.qty,'','',localDay()])]),'text/csv;charset=utf-8');}
    case'add-po-line':root.querySelector('#op-po-lines').insertAdjacentHTML('beforeend',poLine(S.getState()));return;
    case'remove-po-line':if(root.querySelectorAll('.op-po-line').length<=1)throw new Error('Keep at least one PO line.');b.closest('.op-po-line').remove();return;
    case'po-detail':return showPO(id);
    case'edit-po':return editPOModal(id);
  }}catch(error){notice(error.message,true);}}
  function renderTransportation(){layout('transportation','Transportation','Plan freight, consolidate loads and track carrier movements in the transportation workspace.',`<div class="op-module-grid">${NAV.transportation.slice(1).map(([path,label])=>`<a class="op-module-card" href="${S.url(path)}"><strong>${esc(label)}</strong><span>Open workspace →</span></a>`).join('')}</div>`);}
  function render(){switch(page){case'transportation':return renderTransportation();case'orders':case'order-issues':case'order-unvalidated':case'order-cancelled':return renderOrders();case'order-entry':return renderOrderEntry();case'shipping':return renderShipping();case'shipping-daily':return renderDaily();case'tpl':return renderTPLHome();case'tpl-history':return renderHistory();case'tpl-requests':return renderRequestForm();case'tpl-orders':case'tpl-ship':return renderPartnerOrders();case'tpl-upload':return renderUpload();case'tpl-api':return renderIntegrations();case'procurement':return renderProcurement();case'po-entry':return renderPOEntry();}}
  document.addEventListener('DOMContentLoaded',()=>{root=document.querySelector('#fulfillment-content');if(!root || !page)return;render();root.addEventListener('click',actions);window.addEventListener('stark:system-change',()=>{if(!['order-entry','po-entry','tpl-requests','tpl-upload'].includes(page)&&!document.querySelector('.op-modal'))render();});});
  window.StarkFulfillmentPages={render,csv};
})();
